-- 0201_seed_10_niche_islami.sql (2026-08-20)
-- 10 niche Islam baru untuk PUSTAKA TENANT (permintaan owner). Tiap niche = NYAWA sendiri:
-- bahasa visual, busur emosi, pantangan, dan bar mutu disusun dari watak niche itu — BUKAN salinan.
--
-- DUA DOKTRIN VISUAL (keduanya sudah TERBUKTI di pustaka):
--   A. NOL MANUSIA (pola kisah_teladan_islami — 2 video terbit): sejarah suci & alam ghaib.
--      Benda, tempat, dan jejak jadi tokoh. Foto-realistis.
--      → kisah_islami_dramatis · kisah_nabi_rasul_sahabat · akhirat_kematian_ghaib
--        rahasia_fakta_islam · sejarah_peradaban_islam
--   B. MANUSIA BIASA MASA KINI (pola sunnah_harian — 13 test Test Lab 'done'): kehidupan sehari-hari.
--      Animasi 3D bergaya; hanya figur yang dimuliakan yang dilarang.
--      → dosa_taubat_pengampunan · jodoh_cinta_pernikahan · masalah_hidup_islami
--        rezeki_ujian_takdir · islam_psikologi_kehidupan
--
-- CACAT YANG SENGAJA TIDAK DIWARISI: `sunnah_harian` kosong pada `color_palette` + `atmosphere`,
-- sehingga hook-frame & rewrite jatuh ke default HARDCODE (NICHE_DNA_AUDIT_REMEDIATION baris 26).
-- Ke-10 niche di sini mengisi KETIGA kunci inti (base_style/color_palette/atmosphere) — nol fallback senyap.
--
-- Struktur diverifikasi di 4 permukaan: DB 27 kolom · BE `config.py` select(*) salin seluruh baris
-- (dijaga tests/test_dna_niche_sampai_utuh.py) · FE admin & FE tenant = satu editor dari
-- lib/niche-dna.ts (16 properti visual · 5 kunci persona · 8 bagian naskah, ke-8 terisi).
--
-- is_active=false — mengikuti pola seed 0132 (aktivasi = keputusan owner, nol tenant terpapar).
-- is_base=false · access_type=public · origin=admin.

begin;

insert into niches (niche_id, name, description, description_en, keywords, style, target_emotion,
  default_hashtags, narration_persona, visual_style, visual_fallbacks, mood_priority,
  emotion_scoring_criteria, section_timing, image_quality_tags, image_negative_prompt,
  music_config, youtube_category_id, is_active, is_base, access_type, origin)
values
('kisah_islami_dramatis', 'Kisah Islami Dramatis', 'Kisah nyata dari sejarah Islam yang dibawakan seperti film: ada bahaya, ada pilihan yang mustahil, ada titik balik. Ketegangan dulu — maknanya mendarat di akhir, bukan dikhotbahkan di awal. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'A true story from Islamic history told like a film: real danger, an impossible choice, a turning point. Tension first; the meaning lands at the end instead of being preached at the start. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["kisah islami", "kisah dramatis", "sejarah islam", "kisah nyata islami", "titik balik", "keberanian iman", "cerita islami menegangkan"]'::jsonb, 'cinematic Islamic drama, tension-first storytelling', 'tegang lalu tertegun — jantung berdebar, hati tersentuh', '["#KisahIslami", "#KisahDramatis", "#SejarahIslam", "#CeritaIslami", "#IslamicStory", "#KisahNyata", "#TitikBalik", "#HikmahIslam", "#IslamInspirasi", "#Dakwah"]'::jsonb, '{"tone": "pendongeng yang menahan napas penonton — tenang tapi menekan, seperti narator dokumenter drama; tanpa nada ceramah, tanpa teriakan", "style": "bahaya dinyatakan lebih dulu, pilihan mustahil dibuat terasa mahal, titik balik dibuka di klimaks, maknanya cukup satu kalimat di akhir", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · gaya horor atau jumpscare · mendramatisasi sampai melebihi riwayat · membocorkan titik balik di hook · moral dikhotbahkan sebelum ceritanya utuh", "hook_style": "story_open pada detik paling berbahaya dalam kisah itu", "emotion_arc": "bahaya → pilihan yang mustahil → titik balik → hati tertegun"}'::jsonb, '{"render_style": "photorealistic", "base_style": "cinematic historical drama photography, chiaroscuro storytelling, ANICONIC — the objects, places, and traces carry the drama; no human being is ever shown", "color_palette": "storm indigo, torch amber, sand ochre, iron grey, deep night black", "atmosphere": "napas tertahan — bahaya yang belum lewat, keputusan besar yang menggantung di udara", "lighting": "single torch or oil-lamp against heavy darkness, hard shafts through a doorway, storm light, dawn breaking after a long night", "camera": "low dramatic angles on objects, macro on the decisive detail, slow push-in that tightens the chest", "composition": "one decisive object dominant against deep shadow, empty space where a person would be, layered depth", "realism": "hyper-photorealistic — worn leather, wet stone, blown dust, cold iron, physically-based, 8K micro-detail", "color_grading": "high-contrast filmic grade, crushed but living shadows, warm highlight against cold shade", "motion": "one decisive movement per shot — a door swinging, dust settling, a flame bending", "reference": "visual language of premium historical-drama cinema and heritage documentaries", "subject": "benda dan tempat yang menanggung ketegangan cerita — pintu, tali, pedang bersarung, kantong air, jejak kaki", "environment": "gurun malam, lorong batu, tenda, pelabuhan tua, pintu kota, gua", "strict_prohibition": "ABSOLUTE (Islamic aniconism, non-negotiable): NEVER depict any human being in any form or degree — no face, body, hands, silhouette, shadow, back view, crowd, or worn garment implying a body — and NEVER any prophet, messenger, angel, or revered companion. Every scene must be completely unpeopled: architecture, calligraphy, geometric pattern, landscape, sky, and artifacts only. If a scene idea implies a person, replace the person with an object, a place, or a trace they left behind. Any Arabic lettering stays ornamental and never legible.", "camera_motion": {"intensity": "sedang"}}'::jsonb, '["A single oil lamp burning in a stone corridor, hard shadows stretching away, no people", "Storm clouds over an empty desert caravan trail at dusk, tracks still fresh in the sand", "A heavy wooden city gate ajar, torchlight spilling through the gap onto wet stone", "Macro of a coiled rope and a sheathed blade resting on sand, lit by one flame", "Dawn light breaking over an empty rocky valley after a long night, mist in the low ground"]'::jsonb, '["dramatic", "epic", "inspirational", "calm"]'::jsonb, 'Score 80+ if the climax lands A TURNING POINT THAT REFRAMES EVERYTHING — the danger felt real, the choice felt expensive, and the reversal makes the viewer exhale. Valid techniques: opening at the most dangerous second, naming the cost before the reward, withholding the turn until the climax, one sentence of meaning at the very end. STRICT ADAB: dignity over spectacle; never depict or voice a revered figure; no horror styling; never dramatise beyond what the narration is sourced on. Score below 60 if the moral is preached before the story is whole, if the turning point is spoiled in the hook, or if it reads as a lecture with sound effects. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 5, "build_up": 13, "pattern_interrupt": 2, "core_facts": 13, "curiosity_bridge": 3, "climax": 9, "cta": 3}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'people, human figure, face, hands, silhouette of a person, crowd, portrait, blurry, low detail, flat lighting, distorted, deformed, bad proportions, text, words, letters, numbers, legible arabic script, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic surfaces, oversaturated artificial colors', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('dosa_taubat_pengampunan', 'Dosa, Taubat & Pengampunan', 'Untuk orang yang sedang memikul rasa bersalah. Bukan menghakimi, bukan menakut-nakuti — membukakan pintu: bahwa kembali itu mungkin, dan caranya sederhana. Satu beban, satu pintu, satu langkah kecil hari ini. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'For someone carrying guilt. Never judging, never scaring — opening a door: returning is possible, and the way back is simple. One burden, one door, one small step today. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["taubat", "pengampunan", "dosa", "istighfar", "kembali kepada allah", "rasa bersalah", "hijrah hati"]'::jsonb, 'tender restorative clarity', 'lega dan berani kembali — beban terangkat sedikit, ada jalan pulang', '["#Taubat", "#Pengampunan", "#Istighfar", "#KembaliPadaAllah", "#HijrahHati", "#RahmatAllah", "#JanganPutusAsa", "#MuslimHijrah", "#Muhasabah", "#Islami"]'::jsonb, '{"tone": "hangat dan tidak menghakimi, seperti sahabat yang menemani tanpa bertanya apa dosamu — lembut, sabar, tanpa nada ceramah", "style": "beban penonton diakui lebih dulu, pintu ampunan dibuka tanpa syarat yang menakutkan, satu langkah kecil disebut jelas di akhir", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · menyebut jenis dosa secara rinci atau vulgar · menakut-nakuti dengan siksa · nada putus asa · menghakimi masa lalu penonton · menjanjikan ampunan sebagai transaksi", "hook_style": "you_dont_know tentang beban yang penonton sembunyikan", "emotion_arc": "beban diakui → rasa sendiri pecah → pintu terbuka → berani melangkah"}'::jsonb, '{"render_style": "stylized 3D animated", "base_style": "modern 3D animation, natural adult body proportions, intimate low-key interiors opening into light", "color_palette": "night indigo, lamp amber, dawn peach, warm cream, soft charcoal", "atmosphere": "kesendirian yang perlahan dihangatkan — malam yang berat berubah jadi pagi", "lighting": "single warm lamp in a dark room, rain-light on a window, then genuine dawn entering the frame", "camera": "eye level, close and quiet, gentle slow push toward a face or toward an opening door", "composition": "one lone figure small in the frame at first, the light source placed as the destination", "realism": "soft realistic lighting, detailed skin and fabric, believable weight in the shoulders", "color_grading": "cool shadows warming into amber, no harsh contrast", "motion": "small honest gestures — a bowed head lifting, hands unclasping, a door pushed open", "subject": "orang biasa masa kini yang sedang memikul sesuatu — sendiri, lalu bangkit", "environment": "kamar kost malam, musala kecil, tangga rumah, jalan basah selepas hujan, dapur pagi", "hook_frame_people": "yes", "strict_prohibition": "ABSOLUTE: never depict any prophet, messenger, angel, or revered companion — no face, body, silhouette, shadow, or back view. Ordinary present-day people ARE the subject and are encouraged. Modest dress for everyone; no physical contact between unmarried men and women. Any Arabic lettering stays purely ornamental and never legible. Never illustrate the sin itself, and never depict punishment, fire, or torment.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["A young man sitting alone on the edge of a bed at night, one warm lamp beside him, stylized 3D animation", "Rain running down a dark window while a small lamp glows inside a quiet room, warm 3D animated interior", "A door standing open with soft dawn light pouring across the floor, no one in the doorway yet, 3D animated", "Close-up of hands slowly unclasping in a lap, warm lamp light, gentle 3D animation", "A young woman in modest dress stepping into early morning light on a doorstep, warm stylized 3D animation"]'::jsonb, '["calm", "inspirational", "ambient", "uplifting"]'::jsonb, 'Score 80+ if the climax lands THE DOOR IS STILL OPEN — the viewer feels seen in their guilt, then feels a genuine, unconditional way back, and finishes willing to take one small step today. Valid techniques: naming the hidden burden before offering anything, mercy presented as larger than the sin, one concrete small step named at the end. STRICT ADAB: never shame the viewer, never itemise sins, never threaten with punishment, no fatwa on whether a specific sin is forgiven. Score below 60 if it reads as a warning, a guilt-trip, or generic motivational filler. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 4, "build_up": 11, "pattern_interrupt": 2, "core_facts": 14, "curiosity_bridge": 3, "climax": 9, "cta": 3}'::jsonb, 'high detail, sharp focus, cinematic lighting, expressive faces, natural adult proportions, clean rendering', 'chibi, big head, doll proportions, photo, photorealistic, text, words, letters, legible arabic script, deformed hands, extra fingers, revealing clothing, physical intimacy', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('jodoh_cinta_pernikahan', 'Jodoh, Cinta & Pernikahan Islami', 'Tentang rindu, penantian, dan rumah tangga — dibawakan dengan adab. Bukan drama percintaan, bukan janji ''jodoh datang kalau…''. Satu pertanyaan hati per video, dijawab dengan jujur dan menenangkan. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'About longing, waiting, and married life — carried with adab. Not a romance drama, and never a promise that ''the right one comes if you…''. One question of the heart per video, answered honestly and calmly. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["jodoh", "pernikahan islami", "taaruf", "penantian jodoh", "rumah tangga islami", "cinta halal", "kesiapan menikah"]'::jsonb, 'modest hopeful warmth', 'tenang dan berharap — penantian terasa bermartabat, bukan menyiksa', '["#Jodoh", "#PernikahanIslami", "#Taaruf", "#CintaHalal", "#RumahTanggaIslami", "#MenungguJodoh", "#IstikharahJodoh", "#MuslimahMuslim", "#Sakinah", "#Islami"]'::jsonb, '{"tone": "hangat dan sopan, seperti kakak yang sudah menikah dan bicara jujur — tanpa menggoda, tanpa mendramatisasi, tanpa menggurui", "style": "satu pertanyaan hati yang nyata diangkat, dijawab dengan adab dan kejujuran, ditutup dengan sikap yang bisa dipakai hari ini", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · nuansa merayu atau romantis-sensual · menjanjikan jodoh sebagai imbalan ibadah · menyalahkan yang belum menikah · membanding-bandingkan pasangan · membuka aib rumah tangga", "hook_style": "you_dont_know atau pertanyaan yang sudah lama disimpan penonton", "emotion_arc": "rindu diakui → kegelisahan dijernihkan → sikap yang bermartabat → tenang dan berharap"}'::jsonb, '{"render_style": "stylized 3D animated", "base_style": "modern 3D animation, natural adult body proportions, warm domestic scenes of modest everyday life", "color_palette": "soft rose beige, tea amber, warm white, sage green, morning gold", "atmosphere": "kehangatan rumah yang tenang — penantian yang teduh, bukan gelisah", "lighting": "soft morning window light, warm kitchen lamp, late-afternoon gold through curtains", "camera": "eye level, respectful medium shots, gentle drift; hands and objects in close-up instead of lingering faces", "composition": "figures framed separately and never touching, an object of togetherness placed between them", "realism": "soft realistic lighting, detailed fabric and skin, natural modest clothing", "color_grading": "warm gentle grade, low contrast, nothing glamourised", "motion": "quiet domestic actions — pouring tea, folding a prayer mat, writing a letter", "subject": "orang biasa masa kini dalam kehidupan rumah yang sopan", "environment": "dapur pagi, ruang tamu sederhana, halaman rumah, musala keluarga", "hook_frame_people": "yes", "strict_prohibition": "ABSOLUTE: never depict any prophet, messenger, angel, or revered companion — no face, body, silhouette, shadow, or back view. Ordinary present-day people ARE the subject and are encouraged. Modest dress for everyone; no physical contact between unmarried men and women. Any Arabic lettering stays purely ornamental and never legible. Absolutely no physical contact, embrace, or romantic gaze between a man and a woman who are not clearly family; no bedroom scenes; no dating imagery.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["Two cups of tea steaming on a simple wooden table by a bright window, no people, warm 3D animation", "A young woman in modest dress reading by a morning window, calm and self-possessed, stylized 3D animation", "A neatly folded prayer mat and a handwritten note on a bedside table, warm lamp light, 3D animated", "A mother placing her hand on her adult daughter''s shoulder in a sunlit kitchen, warm stylized 3D animation", "A simple wedding invitation card on a table beside fresh flowers, soft afternoon light, 3D animated"]'::jsonb, '["calm", "uplifting", "inspirational", "ambient"]'::jsonb, 'Score 80+ if the climax lands DIGNIFIED HOPE — the viewer''s longing is named without embarrassment, the anxiety around it is untangled, and they finish calmer and more self-respecting. Valid techniques: naming the unspoken question, separating what is in the viewer''s hands from what is not, one dignified stance named at the end. STRICT ADAB: no seduction, no romantic-sensual framing, no promising a spouse as a reward for worship, never blaming the unmarried. Score below 60 if it reads as a romance fantasy, a guilt-trip about being single, or generic motivational filler. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 4, "build_up": 10, "pattern_interrupt": 2, "core_facts": 16, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'high detail, sharp focus, cinematic lighting, expressive faces, natural adult proportions, clean rendering', 'chibi, big head, doll proportions, photo, photorealistic, text, words, letters, legible arabic script, deformed hands, extra fingers, revealing clothing, physical intimacy', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('kisah_nabi_rasul_sahabat', 'Kisah Nabi, Rasul & Sahabat', 'Kisah para nabi, rasul, dan sahabat — dibawakan dengan adab tertinggi. Tokohnya tidak pernah digambarkan maupun disuarakan; yang bercerita adalah tempat, benda, dan jejak yang mereka tinggalkan. Satu kisah, satu pelajaran. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'Stories of the prophets, messengers, and companions, carried with the highest adab. The figures are never depicted or voiced; the places, objects, and traces they left behind carry the story. One story, one lesson. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["kisah nabi", "kisah rasul", "kisah sahabat nabi", "sirah nabawiyah", "sejarah para nabi", "teladan sahabat", "kisah para rasul"]'::jsonb, 'reverent sacred biography, aniconic and monumental', 'khusyuk dan kagum — merasa kecil, lalu ingin meneladani', '["#KisahNabi", "#KisahSahabat", "#SirahNabawiyah", "#KisahRasul", "#TeladanNabi", "#SejarahIslam", "#IslamicHistory", "#Sirah", "#KisahIslami", "#Dakwah"]'::jsonb, '{"tone": "khidmat dan hangat, seperti ustadz yang bercerita seusai maghrib — berwibawa, tenang, tanpa dramatisasi", "style": "riwayat disampaikan dengan hormat dan hati-hati, kejadiannya dibuat konkret lewat tempat dan benda, satu pelajaran mendarat di kehidupan hari ini", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · membuat dialog orang pertama untuk nabi/rasul/sahabat · menambah rincian yang tidak ada dalam riwayat · nada horor atau sensasional · gelar penghormatan ditulis dengan lambang", "hook_style": "story_open pada satu momen yang jarang diketahui dari kisah itu", "emotion_arc": "ketenangan → ujian tersaji → sikap mulia terungkap → hati tergerak meneladani"}'::jsonb, '{"render_style": "photorealistic", "base_style": "monumental sacred-history photography, austere desert-and-stone grandeur, ANICONIC — never depicting any prophet, messenger, angel, or companion in any form", "color_palette": "desert amber, sandstone cream, oasis emerald, night-prayer indigo, moonlit silver", "atmosphere": "kekhusyukan — kesunyian berabad-abad, keagungan yang membuat penonton merasa kecil", "lighting": "desert dawn gold, moonlight on stone, oil-lamp amber in a cave mouth, shafts through a mosque dome", "camera": "slow reverent rises, wide monumental establishing shots, macro on a staff, a mushaf, a water skin", "composition": "sacred-geometry symmetry, the symbolic object as protagonist, vast emptiness where people would be", "realism": "hyper-photorealistic — sandstone grain, worn leather, desert dust in god-rays, oud wood, physically-based, 8K", "color_grading": "warm devotional grade, amber richness against cool night, gentle filmic depth", "motion": "wind moving sand and cloth, light travelling slowly across stone", "reference": "visual language of premium Islamic-heritage documentaries and desert-epic cinematography", "subject": "tempat dan benda yang menyimpan kisahnya — gua, tongkat, mushaf terbuka, kantong air, jejak kafilah", "environment": "gurun, gua, oasis, lembah berbatu, masjid kuno, jalur kafilah", "strict_prohibition": "ABSOLUTE (Islamic aniconism, non-negotiable): NEVER depict any human being in any form or degree — no face, body, hands, silhouette, shadow, back view, crowd, or worn garment implying a body — and NEVER any prophet, messenger, angel, or revered companion. Every scene must be completely unpeopled: architecture, calligraphy, geometric pattern, landscape, sky, and artifacts only. If a scene idea implies a person, replace the person with an object, a place, or a trace they left behind. Any Arabic lettering stays ornamental and never legible. Not even a distant or partial human form is acceptable in this niche.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["Dawn light spilling across an empty desert valley, long shadows on rippled sand, no people", "The mouth of a stone cave lit by a single oil lamp, dust suspended in the beam", "An open mushaf resting on a wooden rehal beside a brass lamp, night stillness", "A worn leather water skin and a wooden staff leaning against a sandstone wall, warm low sun", "Caravan tracks crossing an endless dune field under a vast indigo evening sky"]'::jsonb, '["calm", "inspirational", "epic", "ambient"]'::jsonb, 'Score 80+ if the climax lands A NOBLE ACT MADE CONCRETE — the trial felt costly and the response felt human, so the viewer wants to imitate it today. Valid techniques: the moment told with dignity, the cost made vivid before the outcome, the timeless principle landing on a present-day situation. STRICT ADAB: highest reverence; never depict or voice a revered figure; never invent detail beyond the narration''s source; no sensational styling. Score below 60 if it reads as a dry recitation of names and dates, or as spectacle. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 5, "build_up": 12, "pattern_interrupt": 2, "core_facts": 15, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'people, human figure, face, hands, silhouette of a person, crowd, portrait, blurry, low detail, flat lighting, distorted, deformed, bad proportions, text, words, letters, numbers, legible arabic script, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic surfaces, oversaturated artificial colors', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('akhirat_kematian_ghaib', 'Akhirat, Kematian & Alam Ghaib', 'Pengingat tentang kematian dan kehidupan sesudahnya — menyadarkan, bukan menakut-nakuti. Bukan horor, bukan cerita seram: yang ghaib tidak pernah digambarkan, hanya disebut dengan hormat sesuai riwayat. Satu pengingat per video. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'A reminder about death and what follows — sobering, never frightening. Not horror and not a ghost story: the unseen is never depicted, only mentioned with reverence as the sources describe it. One reminder per video. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["akhirat", "kematian", "alam barzakh", "hari kiamat", "alam ghaib", "muhasabah kematian", "kehidupan setelah mati"]'::jsonb, 'sober luminous remembrance', 'tersadar dan tenang — takut yang menenangkan, bukan takut yang menakutkan', '["#Akhirat", "#Kematian", "#AlamBarzakh", "#HariAkhir", "#Muhasabah", "#IngatMati", "#PengingatDiri", "#Tazkirah", "#Islami", "#RenunganIslam"]'::jsonb, '{"tone": "tenang dan berwibawa, seperti pengingat yang lembut selepas isya — tanpa suara mengancam, tanpa nada horor", "style": "kenyataan kematian disebut apa adanya tanpa dibumbui, disandingkan dengan kehidupan hari ini, ditutup dengan satu amal kecil yang bisa dimulai malam ini", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · gaya horor, suara mengagetkan, atau pacing film seram · menggambarkan malaikat, ruh, jin, atau siksa · merinci yang ghaib tanpa sumber · menakut-nakuti sampai penonton putus asa · membicarakan kematian orang tertentu", "hook_style": "you_dont_know tentang hal sehari-hari yang ternyata pengingat kematian", "emotion_arc": "kesibukan dunia → satu kenyataan yang menghentikan → kesadaran → satu amal kecil malam ini"}'::jsonb, '{"render_style": "photorealistic", "base_style": "quiet contemplative photography of absence, luminous night stillness, ANICONIC and completely unpeopled — the unseen is never illustrated", "color_palette": "night indigo, moonlit slate, cold silver, faint lamp amber, pale dawn grey", "atmosphere": "kesunyian yang menyadarkan — dunia terus berjalan, satu tempat berhenti", "lighting": "moonlight through a window, a lamp burning low, faint pre-dawn grey, no harsh shadow play", "camera": "still and patient framing, slow imperceptible drift, wide night skies and quiet empty interiors", "composition": "emptiness as the subject — an unoccupied space where someone used to be, generous negative space", "realism": "hyper-photorealistic — cotton weave, cooling earth, dust on a sill, condensation on glass, physically-based, 8K", "color_grading": "cool restrained grade, soft highlights, never crushed into horror blacks", "motion": "almost none — a curtain breathing, a flame lowering, dust settling", "reference": "visual language of contemplative documentary photography, not horror cinema", "subject": "ketiadaan dan jejaknya — tempat kosong, kain putih terlipat, tanah, langit malam", "environment": "kamar sunyi malam, halaman pemakaman berumput di pagi berkabut, langit malam terbuka, jendela terbuka", "strict_prohibition": "ABSOLUTE (Islamic aniconism, non-negotiable): NEVER depict any human being in any form or degree — no face, body, hands, silhouette, shadow, back view, crowd, or worn garment implying a body — and NEVER any prophet, messenger, angel, or revered companion. Every scene must be completely unpeopled: architecture, calligraphy, geometric pattern, landscape, sky, and artifacts only. If a scene idea implies a person, replace the person with an object, a place, or a trace they left behind. Any Arabic lettering stays ornamental and never legible. Additionally and absolutely: never depict an angel, a soul or spirit, a jinn, a corpse or shrouded body, a grave being punished, fire, torment, or any horror-film imagery. Absence is shown through empty space and quiet objects only.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["Moonlight falling through an open window onto an empty bed, curtain barely moving, no people", "A vast clear night sky over a silent sleeping town, stars sharp and cold", "A neatly folded white cloth on a wooden bench in a quiet room, soft grey morning light", "Dew on grass in a quiet cemetery lawn at dawn, mist low, no headstone legible", "An oil lamp burning very low on a windowsill, pre-dawn grey outside"]'::jsonb, '["calm", "ambient", "inspirational"]'::jsonb, 'Score 80+ if the climax lands A SOBERING THAT CALMS — the viewer stops, sees their own day differently, and finishes wanting to do one small good thing tonight rather than feeling terrified. Valid techniques: an ordinary daily object revealed as a reminder, the fact of death stated plainly without embellishment, one small deed named at the end. STRICT ADAB: never depict the unseen, never describe torment, never use horror pacing or scare tactics, never claim details of the unseen without a source, never despair. Score below 60 if it reads as a ghost story, a scare video, or generic motivational filler. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 6, "build_up": 12, "pattern_interrupt": 2, "core_facts": 14, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'people, human figure, face, hands, silhouette of a person, crowd, portrait, blurry, low detail, flat lighting, distorted, deformed, bad proportions, text, words, letters, numbers, legible arabic script, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic surfaces, oversaturated artificial colors, horror, gore, ghost, skull, demon, corpse, fire, flames, angel, spirit, supernatural creature', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('masalah_hidup_islami', 'Masalah Kehidupan dalam Perspektif Islam', 'Masalah nyata sehari-hari — utang, atasan sulit, orang tua yang menuntut, rasa sendiri — dilihat dengan kacamata Islam supaya hari ini jadi bisa dijalani. Masalahnya disebut jujur dulu, baru jalan keluarnya. Satu masalah per video. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'Real everyday problems — debt, a difficult boss, demanding parents, loneliness — seen through an Islamic lens so that today becomes workable. The problem is named honestly first, then the way through. One problem per video. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["masalah hidup", "solusi islami", "menghadapi masalah", "nasihat islami", "hidup sesuai islam", "sabar dan ikhtiar", "islam sehari-hari"]'::jsonb, 'grounded practical guidance', 'lega dan tahu langkah berikutnya', '["#MasalahHidup", "#SolusiIslami", "#NasihatIslami", "#HidupIslami", "#SabarDanIkhtiar", "#MuslimSehariHari", "#Muhasabah", "#IslamPraktis", "#Dakwah", "#Islami"]'::jsonb, '{"tone": "membumi dan lugas, seperti teman yang pernah mengalaminya sendiri — jujur, tanpa menggurui, tanpa nada ceramah", "style": "masalahnya disebut apa adanya termasuk bagian yang tidak nyaman, kacamata Islam dipakai untuk menjernihkan, satu langkah konkret disebut jelas di akhir", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · menyederhanakan masalah berat jadi ''sabar saja'' · menyalahkan penonton atas keadaannya · nasihat yang tak bisa dikerjakan orang biasa · fatwa · membuka aib orang", "hook_style": "you_dont_know atau menyebut masalah yang penonton kira hanya dia yang mengalaminya", "emotion_arc": "masalah diakui jujur → merasa tidak sendiri → kacamata yang menjernihkan → satu langkah konkret"}'::jsonb, '{"render_style": "stylized 3D animated", "base_style": "modern 3D animation, natural adult body proportions, everyday Indonesian urban and kampung life rendered with warmth", "color_palette": "warm terracotta, daylight blue, worn concrete grey, market green, lamp amber", "atmosphere": "keseharian yang berat tapi hidup — nyata, ramai, tetap ada cahaya", "lighting": "flat bright tropical daylight, fluorescent office light, warm evening lamp indoors", "camera": "eye level, medium shots that keep the environment visible, gentle handheld feel", "composition": "person placed inside a busy, layered everyday environment rather than isolated", "realism": "soft realistic lighting, detailed fabric and worn surfaces, believable ordinary clothing", "color_grading": "natural grade, honest colours, no glamour", "motion": "ordinary purposeful action — counting money, carrying goods, typing, waiting", "subject": "orang biasa masa kini yang sedang menghadapi urusan sehari-hari", "environment": "warung, angkot, kantor kecil, kamar kost, pasar, ruang tamu rumah sederhana", "hook_frame_people": "yes", "strict_prohibition": "ABSOLUTE: never depict any prophet, messenger, angel, or revered companion — no face, body, silhouette, shadow, or back view. Ordinary present-day people ARE the subject and are encouraged. Modest dress for everyone; no physical contact between unmarried men and women. Any Arabic lettering stays purely ornamental and never legible.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["A young man sitting at a small warung table with a notebook and a glass of tea, bright daylight, stylized 3D animation", "A tired office worker at a cluttered desk under fluorescent light, late afternoon, 3D animated", "Hands counting a small amount of folded banknotes on a wooden table, warm light, 3D animated", "A crowded neighbourhood street in the morning, people going about their work, warm stylized 3D animation", "A woman in modest dress hanging laundry on a small terrace, bright tropical daylight, 3D animation"]'::jsonb, '["calm", "uplifting", "inspirational", "ambient"]'::jsonb, 'Score 80+ if the climax lands ONE STEP I CAN ACTUALLY TAKE — the problem was named honestly including the uncomfortable part, the viewer stopped feeling alone, and they finish knowing exactly what to do next. Valid techniques: stating the problem without softening it, separating what is in their hands from what is not, one concrete step an ordinary person can do today. STRICT ADAB: never reduce a heavy problem to ''just be patient'', never blame the viewer for their circumstances, no fatwa, no advice only a rich person could follow. Score below 60 if it stays abstract, moralises, or ends without a usable step. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 3, "build_up": 9, "pattern_interrupt": 2, "core_facts": 18, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'high detail, sharp focus, cinematic lighting, expressive faces, natural adult proportions, clean rendering', 'chibi, big head, doll proportions, photo, photorealistic, text, words, letters, legible arabic script, deformed hands, extra fingers, revealing clothing, physical intimacy', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('rezeki_ujian_takdir', 'Rezeki, Ujian & Takdir', 'Tentang rezeki yang terasa sempit, ujian yang belum selesai, dan takdir yang belum dipahami — tanpa janji cepat kaya dan tanpa mengajak pasrah lumpuh. Berusaha sungguh-sungguh sambil berdamai dengan hasil. Satu pokok per video. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'About provision that feels tight, a trial that has not ended, and a decree not yet understood — with no get-rich promises and no paralysed fatalism. Striving fully while making peace with the outcome. One subject per video. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["rezeki", "takdir", "ujian hidup", "tawakal", "ikhtiar", "sabar", "qadar"]'::jsonb, 'steady trusting realism', 'tenang dan tetap berusaha — beban tetap ada, tapi tidak lagi mencekik', '["#Rezeki", "#Takdir", "#Tawakal", "#Ikhtiar", "#UjianHidup", "#Sabar", "#Qadar", "#RezekiHalal", "#Muhasabah", "#Islami"]'::jsonb, '{"tone": "tenang dan realistis, seperti orang yang pernah kehilangan dan tetap berdiri — jujur soal beratnya, tanpa nada motivator", "style": "kesempitan diakui tanpa dihaluskan, batas antara usaha dan hasil dijernihkan, ditutup dengan sikap yang menenangkan sekaligus tetap bekerja", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · menjanjikan uang atau kekayaan sebagai imbalan ibadah · nada motivator dan janji cepat kaya · mengajak pasrah tanpa usaha · menyalahkan penonton atas kemiskinannya · menyebut angka penghasilan sebagai bukti", "hook_style": "you_dont_know tentang kesempitan yang penonton kira tanda ia tidak disayang", "emotion_arc": "kesempitan diakui → salah paham soal takdir dibongkar → batas usaha dan hasil jernih → tenang dan tetap bekerja"}'::jsonb, '{"render_style": "stylized 3D animated", "base_style": "modern 3D animation, natural adult body proportions, honest working-life scenes of provision and effort", "color_palette": "dawn amber, market teal, rain grey, rice-sack cream, warm earth brown", "atmosphere": "kerja keras yang sunyi — pagi yang dingin, tangan yang tetap bergerak", "lighting": "cold blue dawn turning warm, rain light, single bulb over a work table at night", "camera": "eye level and close on hands and tools, patient framing, small honest movement", "composition": "hands and work objects dominant, the person''s effort readable without their face carrying it", "realism": "soft realistic lighting, worn tools and fabric, believable tiredness in posture", "color_grading": "natural grade, cool mornings and warm interiors, nothing glamourised", "motion": "repeated honest labour — sweeping, loading, stitching, counting, waiting in rain", "subject": "tangan yang bekerja dan alat kerjanya, orang biasa yang sedang berusaha", "environment": "pasar subuh, warung kecil, bengkel, jalan saat hujan, dapur rumah sederhana", "hook_frame_people": "yes", "strict_prohibition": "ABSOLUTE: never depict any prophet, messenger, angel, or revered companion — no face, body, silhouette, shadow, or back view. Ordinary present-day people ARE the subject and are encouraged. Modest dress for everyone; no physical contact between unmarried men and women. Any Arabic lettering stays purely ornamental and never legible. Never show wealth as a reward: no luxury cars, stacks of cash, or aspirational riches imagery.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["A market stall being set up in cold blue dawn light, crates and vegetables, stylized 3D animation", "Hands stitching at a small work table under a single bulb at night, warm 3D animated interior", "A motorbike parked in the rain outside a small shop, water running off the seat, 3D animated", "An almost empty rice sack in a simple kitchen, morning light through a window, 3D animation", "A simple plate of rice and side dish placed on a worn table, warm daylight, stylized 3D animation"]'::jsonb, '["calm", "inspirational", "ambient", "uplifting"]'::jsonb, 'Score 80+ if the climax lands EFFORT AND PEACE CAN COEXIST — the tightness is acknowledged without sugar-coating, a misunderstanding about decree is corrected, and the viewer finishes calmer yet still willing to work. Valid techniques: naming the fear behind the tightness, drawing a clear line between what is theirs to do and what is not, one steady stance named at the end. STRICT ADAB: never promise money or wealth as a return for worship, never blame the viewer for poverty, no motivational-speaker tone, no fatalism. Score below 60 if it reads as prosperity preaching, a get-rich pep talk, or resignation. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 4, "build_up": 10, "pattern_interrupt": 2, "core_facts": 16, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'high detail, sharp focus, cinematic lighting, expressive faces, natural adult proportions, clean rendering', 'chibi, big head, doll proportions, photo, photorealistic, text, words, letters, legible arabic script, deformed hands, extra fingers, revealing clothing, physical intimacy, luxury car, stacks of cash, gold, mansion', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('islam_psikologi_kehidupan', 'Islam & Psikologi Kehidupan', 'Jembatan antara apa yang dirasakan batin modern — cemas, overthinking, lelah jiwa — dan wawasan Islam tentangnya. Menjelaskan, bukan mendiagnosis; menenangkan, bukan menggantikan bantuan profesional. Satu keadaan batin per video. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'A bridge between what the modern inner life actually feels like — anxiety, overthinking, burnout — and Islamic insight about it. Explaining, not diagnosing; calming, never a replacement for professional help. One inner state per video. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["psikologi islam", "kesehatan mental islami", "overthinking", "cemas", "lelah jiwa", "ketenangan hati", "jiwa dan iman"]'::jsonb, 'lucid inner-life explanation', 'merasa dipahami lalu lebih jernih', '["#PsikologiIslam", "#KesehatanMental", "#Overthinking", "#KetenanganHati", "#JiwaTenang", "#MentalHealthMuslim", "#Muhasabah", "#Tazkiyatunnafs", "#Islami", "#SelfHealing"]'::jsonb, '{"tone": "jernih dan menenangkan, seperti orang yang menjelaskan isi kepala penonton lebih baik dari penonton sendiri — hangat, presisi, tanpa jargon", "style": "keadaan batin dilukiskan sampai penonton merasa ''ini aku'', lalu dijelaskan sebabnya, lalu disandingkan dengan wawasan Islam, ditutup satu latihan kecil", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · mendiagnosis penonton · menyuruh berhenti berobat atau berkonsultasi · mengatakan cemas hilang cukup dengan ibadah · istilah klinis tanpa penjelasan · menyalahkan lemahnya iman atas gangguan jiwa", "hook_style": "you_dont_know yang melukiskan isi kepala penonton dengan tepat", "emotion_arc": "keadaan batin dikenali → ''ternyata ada namanya'' → wawasan yang menjernihkan → satu latihan kecil"}'::jsonb, '{"render_style": "stylized 3D animated", "base_style": "modern 3D animation, natural adult body proportions, quiet interiors where the inner state is made physical through ordinary objects", "color_palette": "muted teal, paper white, dusk lavender, warm lamp amber, soft grey", "atmosphere": "ketenangan yang sedang diusahakan — kepala penuh, ruangan sunyi", "lighting": "soft diffused daylight, screen glow on a face in a dark room, quiet dusk light", "camera": "eye level, close and still, macro on the object standing in for the feeling", "composition": "one person and one telling object, clean uncluttered frame with breathing space", "realism": "soft realistic lighting, detailed skin and fabric, honest tired expressions", "color_grading": "calm low-contrast grade, gentle cool tones warming at the end", "motion": "very little — breathing, a hand set down, a screen turned face-down", "subject": "orang biasa masa kini dan satu benda yang mewakili isi kepalanya", "environment": "kamar sunyi, meja kerja malam, jendela berkabut, musala kecil, taman pagi", "hook_frame_people": "yes", "strict_prohibition": "ABSOLUTE: never depict any prophet, messenger, angel, or revered companion — no face, body, silhouette, shadow, or back view. Ordinary present-day people ARE the subject and are encouraged. Modest dress for everyone; no physical contact between unmarried men and women. Any Arabic lettering stays purely ornamental and never legible. Never depict self-harm, medication, hospital or clinical settings, or anything that reads as a medical claim.", "camera_motion": {"intensity": "halus"}}'::jsonb, '["A tangled pair of earphones on a bedside table lit by one warm lamp, stylized 3D animation", "A young man lying awake staring at the ceiling, phone glow beside him, 3D animated night interior", "A phone placed face-down on a desk beside a cooling cup of tea, quiet dusk light, 3D animated", "Breath fog on a cold window at dawn, a hand resting on the glass, stylized 3D animation", "A woman in modest dress sitting quietly on a prayer mat in soft morning light, 3D animation"]'::jsonb, '["calm", "ambient", "inspirational", "uplifting"]'::jsonb, 'Score 80+ if the climax lands I FINALLY UNDERSTAND WHAT I FEEL — the inner state is described so precisely that the viewer recognises themselves, then the explanation and the Islamic insight make it lighter and clearer. Valid techniques: naming the feeling before explaining it, giving it a plain-language mechanism, pairing it with an Islamic insight that fits rather than overrides, one small practice at the end. STRICT ADAB: never diagnose, never discourage professional help, never say worship alone removes a mental-health condition, never blame weak faith. Score below 60 if it uses clinical jargon without explanation, moralises, or reads as generic self-help. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 3, "build_up": 9, "pattern_interrupt": 2, "core_facts": 18, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'high detail, sharp focus, cinematic lighting, expressive faces, natural adult proportions, clean rendering', 'chibi, big head, doll proportions, photo, photorealistic, text, words, letters, legible arabic script, deformed hands, extra fingers, revealing clothing, physical intimacy, hospital, medication, pills, self harm', '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('rahasia_fakta_islam', 'Rahasia & Fakta Menarik tentang Islam', 'Fakta yang membuat penonton berkata ''saya baru tahu'' — manuskrip, astronomi, matematika, arsitektur, catatan sejarah. Rasa penasaran dulu, kekaguman kemudian. Setiap klaim wajib punya sumber yang bisa dilacak. Satu fakta per video. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'Facts that make the viewer say ''I never knew that'' — manuscripts, astronomy, mathematics, architecture, historical records. Curiosity first, awe second. Every claim must have a traceable source. One fact per video. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["fakta islam", "sejarah islam", "ilmuwan muslim", "manuskrip islam", "penemuan islam", "arsitektur islam", "astronomi islam"]'::jsonb, 'curiosity-first archival discovery', 'kaget lalu bangga — ''saya baru tahu'', lalu ''ternyata dari kita''', '["#FaktaIslam", "#IlmuwanMuslim", "#SejarahIslam", "#PeradabanIslam", "#ManuskripIslam", "#IslamicScience", "#TahukahKamu", "#IslamicHistory", "#WawasanIslam", "#Islami"]'::jsonb, '{"tone": "penasaran dan cermat, seperti kurator museum yang antusias — jelas, presisi, tanpa nada ceramah dan tanpa sensasi", "style": "satu fakta yang mengagetkan dibuka lebih dulu, buktinya ditelusuri dengan konkret, sumbernya disebut, ditutup dengan mengapa itu penting hari ini", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · klaim viral yang belum terverifikasi · membesar-besarkan ''sains membuktikan Al-Quran'' · nada konspirasi · merendahkan bangsa atau agama lain · angka atau tanggal tanpa sumber", "hook_style": "you_dont_know pada satu fakta yang berlawanan dengan dugaan umum", "emotion_arc": "dugaan umum → fakta yang mengagetkan → bukti yang konkret → bangga dan ingin tahu lagi"}'::jsonb, '{"render_style": "photorealistic", "base_style": "museum-grade artifact and manuscript photography, archival discovery aesthetic, ANICONIC and unpeopled — the object is always the protagonist", "color_palette": "parchment cream, ink brown, brass gold, lapis blue, deep archive black", "atmosphere": "keheranan yang tenang — benda tua yang menyimpan sesuatu yang tak diduga", "lighting": "controlled museum spot on a single object, raking light revealing surface texture, cool archive shadow", "camera": "macro and extreme macro on ink, metal, and paper fibre, slow orbit around a single artifact", "composition": "one object centred on clean dark ground, generous negative space, top third left clear for a title", "realism": "hyper-photorealistic — paper fibre, oxidised brass, dried ink, glass, physically-based, 8K micro-detail", "color_grading": "rich archival grade, warm object against cool background, clean highlights", "motion": "slow reveal — light travelling across a page, a page turning by itself, dust drifting", "reference": "visual language of museum documentation and premium science-history documentaries", "subject": "benda yang menyimpan faktanya — manuskrip, astrolab, peta lama, alat ukur, geometri", "environment": "meja arsip, ruang pamer gelap, kubah bergeometri, observatorium tua, perpustakaan lama", "strict_prohibition": "ABSOLUTE (Islamic aniconism, non-negotiable): NEVER depict any human being in any form or degree — no face, body, hands, silhouette, shadow, back view, crowd, or worn garment implying a body — and NEVER any prophet, messenger, angel, or revered companion. Every scene must be completely unpeopled: architecture, calligraphy, geometric pattern, landscape, sky, and artifacts only. If a scene idea implies a person, replace the person with an object, a place, or a trace they left behind. Any Arabic lettering stays ornamental and never legible. Any Arabic script on a manuscript must remain decorative texture and never render as legible words.", "camera_motion": {"intensity": "sedang"}}'::jsonb, '["Extreme macro of aged manuscript paper with ornamental ink strokes, raking museum light, no legible text", "A brass astrolabe on a dark surface under a single controlled spotlight, fine engraving visible", "An old hand-drawn map corner lit at a raking angle, paper fibre and fold lines visible", "Geometric zellige tilework filling the frame, light travelling across the glaze", "The interior dome of an old observatory against a cool dark ground, dust in the light shaft"]'::jsonb, '["inspirational", "ambient", "epic", "calm"]'::jsonb, 'Score 80+ if the climax lands I NEVER KNEW THAT, AND IT MATTERS — a common assumption is overturned by a concrete, sourced fact, and the viewer finishes both surprised and proud. Valid techniques: stating the common assumption first, overturning it with a specific verifiable detail, naming the source plainly, closing on why it still matters. STRICT ADAB: every claim traceable; no unverified viral claims; no ''science proves the Quran'' overreach; no conspiracy tone; never belittle another people or faith. Score below 60 if the fact is vague, unsourced, or already widely known. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 5, "build_up": 8, "pattern_interrupt": 3, "core_facts": 18, "curiosity_bridge": 3, "climax": 7, "cta": 3}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'people, human figure, face, hands, silhouette of a person, crowd, portrait, blurry, low detail, flat lighting, distorted, deformed, bad proportions, text, words, letters, numbers, legible arabic script, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic surfaces, oversaturated artificial colors', '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin'),
('sejarah_peradaban_islam', 'Sejarah & Peradaban Islam', 'Peradaban dalam skala besar — kota yang tumbuh, perpustakaan yang lahir, jalur dagang, kebangkitan dan kejatuhan. Bukan fakta kecil, melainkan gerak zaman dan sebab-sebabnya. Satu babak per video. SATU pokok bahasan per video — satu, bukan dua, bukan daftar. Judul DILARANG memuat angka atau kata jumlah. Tulis ''Rasulullah'' atau ''Nabi'', JANGAN memakai lambang non-Latin apa pun.', 'Civilisation at scale — cities rising, libraries born, trade routes, ascent and collapse. Not small trivia but the movement of an era and its causes. One chapter per video. ONE single subject per video — one, never a list. The title MUST NOT contain a number or quantity word. Write ''Rasulullah'' or ''the Prophet'' in plain letters; never non-Latin symbols.', '["peradaban islam", "sejarah islam", "kejayaan islam", "andalusia", "baghdad", "jalur dagang islam", "kebangkitan dan kejatuhan"]'::jsonb, 'sweeping civilisational documentary', 'kagum dan tergerak melanjutkan — bangga, lalu sadar sedang memegang tongkat estafet', '["#PeradabanIslam", "#SejarahIslam", "#KejayaanIslam", "#Andalusia", "#Baghdad", "#IslamicCivilization", "#IslamicHistory", "#WarisanIslam", "#Dakwah", "#Islami"]'::jsonb, '{"tone": "berwibawa dan luas, seperti narator dokumenter sejarah kelas bioskop — tenang, bertenaga, tanpa nada ceramah", "style": "satu babak dijelaskan lewat sebab dan akibatnya, angka dan tempat dibuat terasa besar, kejatuhan dibahas sejujur kejayaan, ditutup dengan pelajaran untuk hari ini", "avoid": "lambang atau huruf non-Latin apa pun, termasuk lambang penghormatan sesudah nama Nabi — font takarir tidak memilikinya dan akan tampil sebagai KOTAK KOSONG di video; tulis ''Rasulullah'' atau ''Nabi'' saja · bahasa fatwa atau hukum fiqih · polemik mazhab · menyalahkan, menghakimi, atau mempermalukan penonton · klaim dalil tanpa menyebut sumbernya · judul yang menjanjikan JUMLAH (listicle) padahal isinya satu hal · menggambarkan atau menyuarakan Nabi, rasul, malaikat, atau sahabat · membanggakan masa lalu tanpa menyebut kejatuhannya · menyalahkan bangsa lain atas kemunduran · angka dan tanggal tanpa sumber · nada nostalgia yang memelas · merendahkan peradaban lain", "hook_style": "story_open atau you_dont_know pada satu babak yang mengubah arah zaman", "emotion_arc": "skala yang mengagetkan → sebab-sebabnya → kejayaan dan kejatuhannya jujur → tongkat estafet hari ini"}'::jsonb, '{"render_style": "photorealistic", "base_style": "monumental civilisational photography, epic architectural scale, ANICONIC and unpeopled — cities, libraries, and landscapes carry the story", "color_palette": "sandstone gold, andalusian ochre, library ink blue, harbour teal, dusk violet", "atmosphere": "keagungan yang menyapu waktu — sesuatu yang besar pernah berdiri di sini", "lighting": "wide golden-hour raking light across architecture, dawn haze over a city, lamp-lit library interiors at night", "camera": "very wide aerial-scale establishing shots, slow majestic rises along facades, deep receding colonnades", "composition": "monumental symmetry and repetition, vast scale with a single human-free vanishing point", "realism": "hyper-photorealistic — weathered sandstone, glazed tile, parchment and leather bindings, physically-based, 8K", "color_grading": "rich epic grade, warm architecture against cool sky, cinematic depth", "motion": "slow grand movement — light sweeping a courtyard, haze drifting over rooftops, water moving in a channel", "reference": "visual language of cinema-grade civilisation documentaries and architectural photography", "subject": "kota, bangunan, perpustakaan, pelabuhan, dan peta yang menanggung ceritanya", "environment": "kota bertembok, halaman masjid raya, perpustakaan lama, pelabuhan, jalur dagang, benteng", "strict_prohibition": "ABSOLUTE (Islamic aniconism, non-negotiable): NEVER depict any human being in any form or degree — no face, body, hands, silhouette, shadow, back view, crowd, or worn garment implying a body — and NEVER any prophet, messenger, angel, or revered companion. Every scene must be completely unpeopled: architecture, calligraphy, geometric pattern, landscape, sky, and artifacts only. If a scene idea implies a person, replace the person with an object, a place, or a trace they left behind. Any Arabic lettering stays ornamental and never legible. Crowds and market scenes must be shown as architecture, goods, and empty streets — never as people.", "camera_motion": {"intensity": "sedang"}}'::jsonb, '["Aerial-scale view of a walled sandstone city at golden hour, long shadows across rooftops, no people", "A vast old library interior lit by high windows, leather-bound volumes receding into depth", "A grand mosque courtyard at dawn, empty, mist low over the paving", "An old harbour with moored wooden vessels and stacked cargo at first light, no people", "Deep receding arched colonnade with light raking across the columns, dust in the air"]'::jsonb, '["epic", "inspirational", "calm", "dramatic"]'::jsonb, 'Score 80+ if the climax lands THE BATON IS IN MY HAND — the scale of what was built lands emotionally, the causes of both the rise and the fall are named honestly, and the viewer finishes proud yet responsible. Valid techniques: making the scale concrete with a specific sourced figure or place, treating the collapse as seriously as the golden age, closing on what it asks of the viewer today. STRICT ADAB: no nostalgia without accountability, no blaming other peoples for the decline, every figure and date traceable, never belittle another civilisation. Score below 60 if it is a proud list of achievements with no causes, or self-pitying nostalgia. HARD FAIL (score below 60, name it FIRST in weak_areas): (a) the text contains any non-Latin symbol or honorific glyph such as the sallallahu-alayhi-wasallam glyph — the caption font cannot render it and it appears as an empty box on screen; write ''Rasulullah'' or ''Nabi'' in plain letters; (b) the title promises a COUNT of things (''7 tanda'', ''5 cara'') while the video teaches only ONE; (c) the script depicts, voices, or puts first-person dialogue into the mouth of any prophet, messenger, angel, or revered companion; (d) a factual or scriptural claim is asserted without a traceable source.', '{"hook": 3, "mystery_drop": 4, "build_up": 12, "pattern_interrupt": 2, "core_facts": 16, "curiosity_bridge": 3, "climax": 8, "cta": 3}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'people, human figure, face, hands, silhouette of a person, crowd, portrait, blurry, low detail, flat lighting, distorted, deformed, bad proportions, text, words, letters, numbers, legible arabic script, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic surfaces, oversaturated artificial colors', '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin')
